  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 50);
  brush.circle(0, 0, 400);

  // Hills
  brush.fill("#98FB98", 70);
  brush.circle(0, 100, 300);
  brush.circle(0, 200, 200);

  // Sun
  brush.fill("#FFD700", 100);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(0, -100);
  brush.vertex(100, -50);
  brush.endShape(true);

  // Trees
  brush.fill("#333333", 60);
  brush.beginShape();
  brush.vertex(0, 150);
  brush.vertex(0, 170);
  brush.vertex(100, 160);
  brush.endShape(true);
}

